import{_ as e,o as l,c as i,a3 as a}from"./chunks/framework.EDt1A0Ag.js";const c=JSON.parse('{"title":"评测方法论与质检标准 | 全球机场 (AirportMatrix)","description":"AirportMatrix 独立实验室测试流程、网络量化指标体系、晚高峰压测标准与流媒体/AI风控解锁验证方案。","frontmatter":{"title":"评测方法论与质检标准 | 全球机场 (AirportMatrix)","description":"AirportMatrix 独立实验室测试流程、网络量化指标体系、晚高峰压测标准与流媒体/AI风控解锁验证方案。"},"headers":[],"relativePath":"methodology.md","filePath":"methodology.md","lastUpdated":1791019698000}'),s={name:"methodology.md"};function n(r,t,o,d,g,h){return l(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="📊-评测方法论与质检标准" tabindex="-1">📊 评测方法论与质检标准 <a class="header-anchor" href="#📊-评测方法论与质检标准" aria-label="Permalink to &quot;📊 评测方法论与质检标准&quot;">​</a></h1><p>为了彻底摒除主观臆测与商业营销滤镜，<strong>全球机场 (AirportMatrix)</strong> 制定了严谨的标准化网络评测体系。本文档全面公开我们的评测环境、数据采集流程、质量量化模型与加权评分算法。</p><hr><h2 id="🔬-六步标准化测试流程" tabindex="-1">🔬 六步标准化测试流程 <a class="header-anchor" href="#🔬-六步标准化测试流程" aria-label="Permalink to &quot;🔬 六步标准化测试流程&quot;">​</a></h2><p>每个纳入深度评测的服务商必须完整走完以下六阶段闭环评测：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[1. 匿名自费订阅] ──&gt; [2. 节点拓扑逆向与 MTR] ──&gt; [3. 晚高峰全负载压测]</span></span>
<span class="line"><span>                                                               │</span></span>
<span class="line"><span>[6. 综合评分与归档] &lt;── [5. 客户端稳定性与售后] &lt;── [4. AI/流媒体风控检测]</span></span></code></pre></div><ol><li><strong>匿名自费订阅</strong>：测试人员使用普通用户账号与常规支付方式购入主流月付/季付套餐，杜绝厂商针对白名单账号的资源倾斜。</li><li><strong>节点拓扑与路由逆向</strong>：使用深度路由跟踪（MTR）、BGP 路由表分析及 ICMP 时延比对，核验入口机房、跨境过境跳数与出口机房，鉴别真实专线与公网伪专线。</li><li><strong>晚高峰全负载压测</strong>：在 20:00 - 23:30（骨干网拥塞极值窗口），运行自研自动化探针持续采集丢包率、延迟抖动与多线程峰值带宽。</li><li><strong>AI 与流媒体风控矩阵检测</strong>：调用自动化检测脚本验证 Netflix 非自制剧、Disney+、YouTube Premium，并调用 OpenAI / Anthropic 接口验证 IP 纯净度与欺诈评分。</li><li><strong>客户端兼容与容灾演练</strong>：测试在断网重连、节点主备切换及主流客户端（Clash Verge Rev、Sing-box、Surge、Shadowrocket）下的配置渲染与协议兼容性。</li><li><strong>评分模型量化归档</strong>：输入采集数据至量化评分系统，输出雷达图与评测结论，所有原始日志归档存证。</li></ol><hr><h2 id="📐-五大核心量化指标与判定阈值" tabindex="-1">📐 五大核心量化指标与判定阈值 <a class="header-anchor" href="#📐-五大核心量化指标与判定阈值" aria-label="Permalink to &quot;📐 五大核心量化指标与判定阈值&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">指标维度</th><th style="text-align:left;">采集工具与方法</th><th style="text-align:left;">优秀阈值（A 级）</th><th style="text-align:left;">可用阈值（B 级）</th><th style="text-align:left;">警戒阈值（C 级）</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>晚高峰丢包率</strong></td><td style="text-align:left;">MTR 连续 500 次 ICMP/TCP 探测 (20:30-22:30)</td><td style="text-align:left;">&lt; 1.0%</td><td style="text-align:left;">1.0% ~ 5.0%</td><td style="text-align:left;">&gt; 8.0%</td></tr><tr><td style="text-align:left;"><strong>延迟抖动 (Jitter)</strong></td><td style="text-align:left;">分布式探针连续计算延迟标准差 ($\\sigma$)</td><td style="text-align:left;">$\\sigma \\le 5\\text{ms}$</td><td style="text-align:left;">$5\\text{ms} &lt; \\sigma \\le 20\\text{ms}$</td><td style="text-align:left;">$\\sigma &gt; 40\\text{ms}$</td></tr><tr><td style="text-align:left;"><strong>单线程吞吐</strong></td><td style="text-align:left;">YouTube 4K/8K 视频首帧与 Connection Speed</td><td style="text-align:left;">$\\ge 80,000\\text{ Kbps}$</td><td style="text-align:left;">$30,000 \\sim 80,000\\text{ Kbps}$</td><td style="text-align:left;">$&lt; 15,000\\text{ Kbps}$</td></tr><tr><td style="text-align:left;"><strong>IP 欺诈分 (Fraud)</strong></td><td style="text-align:left;">IPQualityScore / Scamalytics 风险库检索</td><td style="text-align:left;">$\\text{Score} &lt; 15$</td><td style="text-align:left;">$15 \\le \\text{Score} &lt; 40$</td><td style="text-align:left;">$\\text{Score} \\ge 60$</td></tr><tr><td style="text-align:left;"><strong>节点可用率 (SLA)</strong></td><td style="text-align:left;">7×24 小时每 5 分钟健康心跳探活</td><td style="text-align:left;">$\\ge 99.5%$</td><td style="text-align:left;">$98.0% \\sim 99.5%$</td><td style="text-align:left;">$&lt; 95.0%$</td></tr></tbody></table><hr><h2 id="🛠️-底层拓扑鉴别标准" tabindex="-1">🛠️ 底层拓扑鉴别标准 <a class="header-anchor" href="#🛠️-底层拓扑鉴别标准" aria-label="Permalink to &quot;🛠️ 底层拓扑鉴别标准&quot;">​</a></h2><p>市场中存在大量以“廉价中转”冒充“专线”的现象。实验室采用严格的物理时延常数进行技术甄别：</p><ul><li><strong>真 IPLC / IEPL 专线</strong>： <ul><li>上海 - 日本物理延迟约为 $25\\text{ms} \\sim 32\\text{ms}$；</li><li>深圳 - 香港物理延迟约为 $4\\text{ms} \\sim 7\\text{ms}$；</li><li>全天 24 小时延迟波动稳定在 $\\pm 2\\text{ms}$ 以内，不经过公网国际出口路由器（如 202.97 或 59.43），晚高峰零丢包。</li></ul></li><li><strong>公网中继（Transit Tunnel）</strong>： <ul><li>国内入口通过公网中转服务器汇聚，再经公网 163 骨干网出海；</li><li>晚高峰延迟显著上浮（+30ms 至 +100ms），丢包率超过 5%~15%。</li></ul></li><li><strong>直连线路（Direct BGP）</strong>： <ul><li>无国内中转入口，客户端直连海外节点；</li><li>易受运营商 QOS 流量整形与 DNS 污染影响，稳定性随地区和时段波动极大。</li></ul></li></ul><hr><h2 id="🤖-ai-工具与流媒体解锁测试方案" tabindex="-1">🤖 AI 工具与流媒体解锁测试方案 <a class="header-anchor" href="#🤖-ai-工具与流媒体解锁测试方案" aria-label="Permalink to &quot;🤖 AI 工具与流媒体解锁测试方案&quot;">​</a></h2><p>海外高端平台对机房 IP 实施严格的风控阻断。我们的验证规范如下：</p><h3 id="_1-openai-chatgpt-解锁检测" tabindex="-1">1. OpenAI / ChatGPT 解锁检测 <a class="header-anchor" href="#_1-openai-chatgpt-解锁检测" aria-label="Permalink to &quot;1. OpenAI / ChatGPT 解锁检测&quot;">​</a></h3><ul><li>访问 <code>chatgpt.com</code> 与 <code>api.openai.com</code>；</li><li>验证是否出现 Cloudflare Turnstile 循环人机验证或 <code>Access Denied</code> (1020/403)；</li><li>验证是否被降级至 <code>GPT-4o mini</code> 限制模式或阻断登录；</li><li>判定标准：纯净住宅双 ISP IP &gt; 原生机房双 ISP IP &gt; 广播机房 IP。</li></ul><h3 id="_2-流媒体全解锁检测" tabindex="-1">2. 流媒体全解锁检测 <a class="header-anchor" href="#_2-流媒体全解锁检测" aria-label="Permalink to &quot;2. 流媒体全解锁检测&quot;">​</a></h3><ul><li><strong>Netflix</strong>：必须能播放地区限定非自制版权剧（例如日区、韩区独立版权番剧），而非仅能播放 Netflix Originals 自制剧；</li><li><strong>Disney+</strong>：必须能正常加载首页海报流并无报错开启 4K HDR 杜比视界码流；</li><li><strong>YouTube Premium</strong>：定位地区与免翻广政策需精准匹配。</li></ul><hr><h2 id="⚖️-综合评级加权算法" tabindex="-1">⚖️ 综合评级加权算法 <a class="header-anchor" href="#⚖️-综合评级加权算法" aria-label="Permalink to &quot;⚖️ 综合评级加权算法&quot;">​</a></h2><p>每篇评测的总评分依据以下加权公式严格计算：</p><p>$$\\text{Final Score} = S_{\\text{稳定}} \\times 0.35 + S_{\\text{速度}} \\times 0.25 + S_{\\text{解锁}} \\times 0.20 + S_{\\text{性价比}} \\times 0.15 + S_{\\text{易用}} \\times 0.05$$</p><ul><li><strong>网络稳定性 ($35%$)</strong>：晚高峰丢包表现、多运营商（电信/联通/移动）互通性、SLA 探活历史。</li><li><strong>速度与带宽 ($25%$)</strong>：高峰期突发带宽、大文件拉取速率、YouTube 4K 秒开缓冲。</li><li><strong>解锁与纯净度 ($20%$)</strong>：住宅双 ISP 占比、流媒体跨区完整度、AI 工具风控豁免率。</li><li><strong>性价比与售后 ($15%$)</strong>：月付门槛、工单响应时效、Telegram 运维交流群透明度。</li><li><strong>客户端支持 ($5%$)</strong>：一键订阅转换、主流核心适配文档完整度。</li></ul><hr><h2 id="📌-数据有效期与版本声明" tabindex="-1">📌 数据有效期与版本声明 <a class="header-anchor" href="#📌-数据有效期与版本声明" aria-label="Permalink to &quot;📌 数据有效期与版本声明&quot;">​</a></h2><ul><li><strong>评测周期</strong>：每季度对排行榜核心品牌进行数据复测；</li><li><strong>重大变动触发</strong>：若遇国际海底光缆中断、大规模出口波动或品牌主控更换，实验室将在 7 个工作日内启动加急重测并在对应评测页面标注更新；</li><li><strong>历史归档</strong>：历史版本测速记录移入归档库，保障长期可信度与读者知情权。</li></ul>`,29)])])}const p=e(s,[["render",n]]);export{c as __pageData,p as default};
